/* Browser-only hackathon prototype. No authentication, AI, or medical analysis. */
const D=window.DEMO;
const state={page:location.hash.slice(1)||'landing',persona:'raj',filter:'All',search:'',messages:[],queues:{raj:[...D.initialQueue],maya:['What was your first job, and what did it teach you?','What was Mom like as a child?','What tradition do you hope we keep?']},recordStage:'ready',largeText:false,voiceMetric:'pace',voiceScenario:null,voiceAsOf:null,recordSeconds:0,saved:{raj:0,maya:0},permissions:{raj:{},maya:{}},consent:{raj:true,maya:true},visibility:{raj:'Family',maya:'Family'},selectedPerson:null,busy:false};
let recordTimer,audioTimer,toastTimer,activeAudio,previousFocus;
const icons={arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',stories:'<path d="M5 3h12l3 3v15H5zM17 3v4h4M8 11h9M8 15h9"/>',ask:'<path d="M21 11a8 8 0 0 1-8 8H6l-4 3 2-6a8 8 0 0 1-2-5 9 9 0 0 1 19 0Z"/><path d="M8 10h8M8 14h5"/>',scrapbook:'<path d="M3 4h18v16H3zM3 15l5-5 4 4 3-3 6 6"/><circle cx="16" cy="8" r="1"/>',family:'<circle cx="12" cy="5" r="3"/><path d="M12 8v5M5 16v-3h14v3"/><circle cx="5" cy="19" r="3"/><circle cx="19" cy="19" r="3"/>',voice:'<path d="M3 12h3l2-7 4 14 3-10 2 3h4"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/><path d="m8 12 3 3 5-6"/>',mic:'<rect x="9" y="2" width="6" height="13" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8"/>',play:'<path d="m9 5 10 7-10 7z"/>',pause:'<path d="M8 5v14M16 5v14"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',bell:'<path d="M5 16h14l-2-4V8a5 5 0 0 0-10 0v4zM10 20h4"/>',check:'<path d="m5 12 4 4L19 6"/>',plus:'<path d="M12 4v16M4 12h16"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4M12 14v3"/>',queue:'<path d="M8 6h13M8 12h13M8 18h13M3 6h1M3 12h1M3 18h1"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',heart:'<path d="M20 5c-3-3-6-1-8 1-2-2-5-4-8-1-4 4 1 9 8 15 7-6 12-11 8-15Z"/>',phone:'<rect x="6" y="2" width="12" height="20" rx="3"/><path d="M10 18h4"/>',logout:'<path d="M10 4H4v16h6M10 12h11m-4-4 4 4-4 4"/>'};
const I=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.heart}</svg>`;
const esc=(s)=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const p=()=>D.personas[state.persona];
const title=s=>state.persona==='maya'&&s.mayaTitle?s.mayaTitle:s.title;
const transcript=s=>state.persona==='maya'&&s.mayaTranscript?s.mayaTranscript:s.transcript;
const brand=()=>`<a class="brand" href="#landing" aria-label="${esc(D.brand)} home"><img src="assets/flower.svg" alt="">${esc(D.brand)}</a>`;
const avatar=(person=p(),large=false)=>`<div class="avatar ${large?'lg':''} ${person.id==='maya'?'maya':''}" aria-label="${esc(person.name)}">${esc(person.initials||person.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</div>`;
const btn=(label,page,variant='',icon='arrow')=>`<button class="button ${variant}" data-go="${page}">${label}${icon?I(icon):''}</button>`;
const wave=(count=35)=>`<div class="waveform" aria-hidden="true">${Array.from({length:count},(_,i)=>`<span style="height:${7+((i*17+i*i*3)%29)}px;animation-delay:${(i%7)*.07}s"></span>`).join('')}</div>`;
const nav=[['home','Home','home'],['stories','Stories','stories'],['ask','Ask the archive','ask'],['queue','Question queue','queue'],['scrapbook','Scrapbook','scrapbook'],['family','Family tree','family'],['voice','Voice patterns','voice'],['privacy','Privacy & access','shield']];
function landing(){return `<div class="page"><a class="skip-link" href="#main">Skip to content</a>
<header class="public-nav">${brand()}<nav aria-label="Main navigation"><a href="#how-it-works">How it works</a><a href="#memories">The family archive</a><a href="#plans">Plans</a><a href="#trust">Made with care</a></nav><div class="nav-right"><button class="text-button" data-go="elder">Our app</button>${btn('Explore the demo','home','small')}</div></header>
<main id="main"><section class="hero"><div class="hero-copy"><span class="eyebrow">${I('heart')} For the people who make us, us</span><h1><span>A better way to remember them.</span><span>Remember us.</span><span>Remember you.</span></h1><p>Always with you. Preserve the stories, traditions, and real voices that make your family yours.</p><div class="hero-actions">${btn('Open the family archive','home')}${btn('See our app','elder','secondary','phone')}</div><p class="uvp">The AI never pretends to be Grandma. It helps you rediscover her real words, with every answer linked to the original audio.</p><div class="hero-trust">${I('lock')} Private by choice. Real recordings. A legacy that lasts.</div></div><div class="hero-art"><img class="hero-photo" src="assets/family.jpg" alt="A family sharing a quiet moment together"><span class="image-caption">A little moment. A lasting memory.</span><div class="memory-note"><span class="eyebrow" style="margin:0;font-size:9px">From Raj’s story collection</span><p class="quote">“It was a whole lifetime,<br>in one conversation.”</p><div class="play-line"><button class="circle-play" data-story="love" aria-label="Explore Raj’s wedding memory">${I('play')}</button>${wave(30)}<span class="tiny muted">4:23</span></div><p class="tiny muted" style="margin-top:9px">How I Met Your Grandmother · Demo story</p></div><img class="flower-decoration" src="assets/flower.svg" alt=""></div></section>
<div class="promise-strip"><span>${I('mic')} Their original voice</span><span>${I('stories')} Stories, beautifully organized</span><span>${I('ask')} Answers rooted in real memories</span><span>${I('shield')} Your family. Your access.</span></div>
<section class="public-section" id="how-it-works"><div class="section-intro"><span class="eyebrow">A simple beginning. A lasting connection.</span><h2>A lifetime of stories.<br>One question at a time.</h2><p>No blank pages. No pressure to write a memoir. Just a familiar question and a moment to remember.</p></div><div class="steps"><article class="step"><div class="step-number">01 / ASK ${I('ask')}</div><h3>Start with a question.</h3><p>Send Grandpa something you’ve always wanted to know. A childhood memory. A family recipe. How it all began.</p></article><article class="step"><div class="step-number">02 / PRESERVE ${I('mic')}</div><h3>Let them tell it.</h3><p>One big button. One answer, in their own voice. Each story finds its place in a growing family archive.</p></article><article class="step"><div class="step-number">03 / REDISCOVER ${I('heart')}</div><h3>Come back to their words.</h3><p>Ask the archive a question, find the memory, and hear the original recording. Their words, exactly as they told them.</p></article></div></section>
<section class="feature-band"><div class="feature-inner"><div><span class="eyebrow">A conversation with the archive</span><h2>A question today.<br>A memory forever.</h2><p>Discover what they actually said. Every answer leads back to a recording, so the story stays theirs.</p>${btn('Ask Grandpa’s archive','ask')}</div><div class="example-chat"><div class="row">${avatar(D.personas.raj)}<div><strong>Raj’s family archive</strong><p class="tiny muted" style="margin:2px 0 0">47 stories · a lifetime of memories</p></div><span class="pill blue" style="margin-left:auto">Demo</span></div><div class="chat-question">How did Grandpa meet Grandma?</div><p>Raj met Maya at his cousin’s wedding in Mumbai in 1968. A mutual friend introduced them, and they spent most of the evening talking.</p><div class="source-mini"><div class="row">${I('stories')}<div><strong>How I Met Your Grandmother</strong><p class="tiny muted">Original recording · 1:12–1:54</p></div></div><button class="text-button" data-story="love" style="margin-top:13px">${I('play')} Explore the source ${I('arrow')}</button></div></div></div></section>
<section class="public-section" id="memories"><div class="between section-head"><div><span class="eyebrow">More than an archive</span><h2>The little things.<br>The whole story.</h2></div><button class="text-button" data-go="scrapbook">Explore the scrapbook ${I('arrow')}</button></div><div class="archive-showcase"><button class="photo-tile icon-button" data-story="love" style="padding:0;text-align:left"><img src="assets/family.jpg" alt="Family togetherness"><div class="photo-tile-text"><span class="eyebrow">Love & family</span><h3>Where our story began</h3></div></button><button class="photo-tile icon-button" data-story="food" style="padding:0;text-align:left"><img src="assets/food.jpg" alt="Food prepared with care"><div class="photo-tile-text"><span class="eyebrow">Traditions worth keeping</span><h3>A taste of home</h3></div></button><button class="photo-tile icon-button" data-story="america" style="padding:0;text-align:left"><img src="assets/journey.jpg" alt="A peaceful landscape and water"><div class="photo-tile-text"><span class="eyebrow">New beginnings</span><h3>The places we carry</h3></div></button></div><p class="tiny muted" style="margin-top:15px">Illustrative family stories and photography for the demo.</p></section>
<section class="public-section" id="plans"><div class="section-intro"><span class="eyebrow">Start free. Grow with your family.</span><h2>Simple plans for<br>every family.</h2><p>Illustrative pricing for the prototype. Recording a story is always free.</p></div><div class="plans"><article class="plan"><span class="eyebrow">Free</span><h3>Keep the voice</h3><p class="price">$0</p><ul><li>${I('check')} Raw recordings</li><li>${I('check')} Full transcripts</li><li>${I('check')} Weekly rotating questions</li></ul>${btn('Start recording','elder','secondary','mic')}</article><article class="plan featured"><span class="pill">Most families choose this</span><h3>Family archive</h3><p class="price">$8–15<small>/month</small></p><ul><li>${I('check')} Digital scrapbook and timeline</li><li>${I('check')} Topics and chapters</li><li>${I('check')} Ask the archive, with “Hear Grandma tell it” sources</li><li>${I('check')} Unlimited stories</li></ul>${btn('Explore the archive','home')}</article><article class="plan"><span class="eyebrow">Optional add-on</span><h3>Voice patterns</h3><p class="price">+$10–20<small>/month</small></p><ul><li>${I('check')} Requires the storyteller’s consent</li><li>${I('check')} Compared with their own baseline</li><li>${I('check')} Compared only with their own earlier recordings</li></ul>${btn('See voice patterns','voice','secondary','arrow')}</article></div><p class="tiny muted" style="margin-top:18px">A one-time Legacy option ($199–499) would add a lifetime archive and a professional digital memoir. All figures are hypotheses to validate.</p></section>
<section class="public-section" id="trust" style="padding-top:0"><div class="trust-section"><div><span class="eyebrow">Built around trust</span><h2>Their voice belongs<br>to them. Always.</h2><p class="muted" style="margin-top:20px;font-size:14px;max-width:360px">A family archive should feel like a safe place. Your storyteller decides what to share, and who gets to listen.</p><button class="text-button" data-go="privacy" style="margin-top:20px">Explore privacy controls ${I('arrow')}</button></div><div class="trust-list"><div class="trust-item">${I('mic')}<strong>Original voices</strong><p>No voice cloning or impersonation.</p></div><div class="trust-item">${I('shield')}<strong>Approved access</strong><p>Share with family or selected people.</p></div><div class="trust-item">${I('stories')}<strong>Answers with sources</strong><p>Find the words behind every answer.</p></div><div class="trust-item">${I('download')}<strong>Your archive, to keep</strong><p>Explore export and ownership controls.</p></div></div></div></section>
<section class="final-cta"><img src="assets/flower.svg" alt="" style="width:42px;margin:0 auto 21px"><h2>There’s a story only they can tell.</h2><p>Start with one question. Keep something irreplaceable.</p>${btn('Explore the family demo','home','light')}</section></main><footer class="public-footer">${brand()}<div class="footer-links"><span>Interactive prototype</span><a href="#privacy">Privacy</a><button class="text-button tiny" data-go="elder">Our app</button></div></footer></div>`;}
function shell(content){const person=p();return `<div class="app-shell"><aside class="sidebar">${brand()}<div class="family-switch"><label for="family-select">Your family archive</label><select id="family-select" aria-label="Switch demo family"><option value="raj" ${state.persona==='raj'?'selected':''}>Tekwani family · Raj</option><option value="maya" ${state.persona==='maya'?'selected':''}>Patel family · Maya</option></select></div><nav aria-label="Archive navigation">${nav.map(([id,label,icon])=>`<button class="nav-item ${state.page===id?'active':''}" data-go="${id}" ${state.page===id?'aria-current="page"':''}>${I(icon)}${label}${id==='queue'?`<span class="nav-count">${state.queues[state.persona].length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom">${btn('Open our app','elder','small secondary','phone')}<div class="account">${avatar({name:person.customer})}<div><strong>${esc(person.customer)}</strong><p>Family customer · Demo</p></div></div></div></aside><main class="app-main"><header class="app-topbar"><div class="breadcrumb">${esc(person.family)} family <span>/</span> ${nav.find(n=>n[0]===state.page)?.[1]||'Our app'}</div><div class="topbar-tools"><span class="demo-label">INTERACTIVE DEMO</span><button class="icon-button" data-action="notifications" aria-label="View family notifications">${I('bell')}</button>${avatar({name:person.customer})}</div></header><div class="workspace page">${content}</div></main></div>`;}
const pageTitle=(heading,sub,action='')=>`<div class="page-title"><div><span class="eyebrow" style="font-size:10px;margin-bottom:10px">The ${esc(p().family)} family archive</span><h1>${heading}</h1><p>${sub}</p></div>${action}</div>`;
function storyCard(s){return `<article class="story-card" tabindex="0" role="button" aria-label="Open ${esc(title(s))}" data-story="${s.id}"><div class="story-thumb"><img loading="lazy" src="assets/${s.image}" alt="Illustrative ${esc(s.category.toLowerCase())} photograph"><span class="thumb-play">${I('play')}</span><span class="duration">${s.length}</span></div><div class="story-card-body"><span class="eyebrow">${s.category}</span><h3>${title(s)}</h3><p>“${s.quote}”</p><div class="story-card-footer"><span>${s.date}</span>${I('arrow')}</div></div></article>`;}
function home(){const person=p();return pageTitle(`Some stories stay with us.`,`Keep discovering the little things that make your family yours.`,btn(`Add a question for ${person.first}`,'queue','','plus'))+`<div class="dashboard-columns"><div><section class="card storyteller-card">${avatar(person,true)}<div class="storyteller-info"><span class="eyebrow" style="font-size:9px;margin:0">Your storyteller</span><h2>${person.name}</h2><p class="tiny muted">${person.relation} · ${person.age} years · ${person.route}</p><div class="row">${btn('Record a story','elder','small','mic')}<span class="pill">${I('lock')} Family access</span></div></div><img class="storyteller-flower" src="assets/flower.svg" alt=""></section><section class="stats" aria-label="Archive statistics"><div class="stat"><strong>${person.count+state.saved[state.persona]}</strong><p>stories preserved</p></div><div class="stat"><strong>${person.hours}</strong><p>of their real voice</p></div><div class="stat"><strong>6</strong><p>family members connected</p></div></section><div class="section-title"><h3>Recent memories</h3><button class="text-button tiny" data-go="stories">All stories ${I('arrow')}</button></div><div class="story-grid two">${D.stories.slice(0,2).map(storyCard).join('')}</div><div class="section-title"><h3>A question brings us closer.</h3></div><div class="card note-card between"><div><h3>What have you always wanted to ask?</h3><p>A small question can uncover an extraordinary memory.</p><button class="text-button" data-go="queue">Add to ${person.first}’s question queue ${I('arrow')}</button></div>${I('ask')}</div></div><div class="stack"><section class="card prompt-card"><span class="eyebrow">This week’s question</span><span class="pill warm">One question. One memory.</span><h3>“${esc(state.queues[state.persona][0]||D.initialQueue[0])}”</h3>${btn(`Open ${person.first}’s app`,'elder','','mic')}<p class="tiny muted">A gentle invitation to tell a story.</p></section><section class="card"><h3>A life, in chapters</h3><p class="tiny muted" style="margin-top:8px">Room for every part of their story.</p>${D.chapters.map(([name,count,percent])=>`<div class="chapter"><div class="between"><span>${name}</span><span class="muted">${state.persona==='raj'?count:Math.round(count*.68)} stories</span></div><div class="progress"><span style="width:${percent}%"></span></div></div>`).join('')}<div class="voice-mini"><span class="dot ${vFlags()?'amber':''}"></span><div><strong>${!state.consent[state.persona]?'Voice patterns are off':vFlags()?'Some patterns differ from usual':`Patterns are typical for ${person.first}`}</strong><p>${!state.consent[state.persona]?'Turn on consent to see how recordings compare with earlier ones.':vFlags()?`See which measures moved from ${person.first}’s usual range.`:`Recordings stay within ${person.first}’s usual range.`}</p><button class="text-button tiny" data-go="voice">View voice patterns ${I('arrow')}</button></div></div></section></div></div>`;}
function stories(){return pageTitle('Every story has a place.','Explore memories by moment, person, place, or tradition.',btn('Record a story','elder','','mic'))+`<div class="search-bar">${I('search')}<input id="story-search" placeholder="Search ${p().first}’s stories…" aria-label="Search stories" value="${esc(state.search)}"></div><div class="filters">${['All','Childhood','Love & family','Traditions','New beginnings','Life lessons'].map(f=>`<button class="filter-chip ${state.filter===f?'active':''}" data-filter="${f}">${f}</button>`).join('')}</div><div class="between" style="margin-bottom:18px"><span id="story-count" class="tiny muted"></span><span class="tiny muted">Sample from ${p().count} preserved stories</span></div><div id="story-results" class="story-grid"></div>`;}
function updateStoryResults(){const node=document.querySelector('#story-results');if(!node)return;const list=D.stories.filter(s=>(state.filter==='All'||s.category===state.filter)&&`${title(s)} ${s.tags.join(' ')} ${transcript(s)} ${s.category}`.toLowerCase().includes(state.search.toLowerCase()));node.innerHTML=list.map(storyCard).join('')||'<div class="empty-state">No stories found. Try a different word or chapter.</div>';document.querySelector('#story-count').textContent=`${list.length} memories to explore`;}
function questions(){return D.questions.map(q=>state.persona==='maya'?q.replace(/Grandpa/g,'Grandma').replace(/Grandma\?$/,'Grandpa?').replace('he do','she do').replace(/his /g,'her ').replace('him?','her?').replace('he give','she give'):q);}
function ask(){return pageTitle(`A question. Their real words.`,`Ask about ${p().first}’s life. Every answer points back to a recorded story.`)+`<div class="ask-layout"><section class="card chat-panel"><div class="chat-intro"><img class="chat-flower" src="assets/flower.svg" alt=""><h2>What would you like to know?</h2><p>Explore ${p().relation}’s memories in a new way. Answers come from this archive, with the original story always close by.</p><div class="suggested">${[questions()[0],questions()[4],questions()[3],questions()[6]].map(q=>`<button class="suggestion" data-question="${esc(q)}">${q}</button>`).join('')}</div></div><div id="chat-messages" class="chat-messages" aria-live="polite">${state.messages.map(messageHTML).join('')}</div><form id="ask-form" class="chat-compose"><input id="ask-input" aria-label="Ask a question about the archive" placeholder="Ask about a memory…" autocomplete="off" required maxlength="400"><button class="button small" type="submit">${I('arrow')}<span>Ask</span></button></form><div class="chat-footnote">${I('shield')} Original stories. No impersonation. Hardcoded demo answers.</div></section><aside class="stack"><section class="card context-card">${avatar(p(),true)}<span class="eyebrow" style="font-size:9px">You’re exploring</span><h3>${p().name}’s archive</h3><p>${p().route}<br>Recording since ${p().since}</p><div class="mini-stat"><strong>${p().count}</strong><p>stories, told in their own voice</p></div></section><section class="card note-card"><span class="eyebrow" style="font-size:9px">A memory missing?</span><h3>Ask them next time.</h3><p>If a story hasn’t been told, add your question to the queue. The archive will never make up an answer.</p><button class="text-button tiny" data-go="queue">See the question queue ${I('arrow')}</button></section></aside></div>`;}
function answerFor(question){const q=question.toLowerCase();let id;
if(/wedding|where was|meet|met (grand|dev|maya)/.test(q))id='love';else if(/america|immigra|\bmov(?:e|ed|ing)\b|first came|seattle|phoenix/.test(q))id='america';else if(/diwali|festival/.test(q))id='diwali';else if(/food|cook|recipe|roti|dal/.test(q))id='food';else if(/marriage|advice.*marry/.test(q))id='advice';else if(/job|work|career/.test(q))id='job';else if(/father|mother|dad|mom|child.*like/.test(q))id='father';else if(/school/.test(q))id='school';else if(/first home/.test(q))id='home';
if(!id)return {answer:`I couldn’t find anything in ${p().first}’s recordings about that yet.`,missing:true,question};
const s=D.stories.find(x=>x.id===id);let answer;
if(id==='love')answer=state.persona==='raj'?(/where|location/.test(q)?'Raj said the wedding was in a community hall near Dadar in Mumbai. He remembered the marigolds at the entrance.':'Raj said he met Maya at his cousin’s wedding in Mumbai in 1968. A mutual friend introduced them, and they spent most of the evening talking.'): (/where|location/.test(q)?'Maya said the celebration was at her aunt’s home in Ahmedabad. Everyone had gathered in the courtyard.':'Maya said she met Dev at a family celebration in Ahmedabad in 1967. Her aunt introduced them, and they spent the evening talking about books they both loved.');
else if(id==='america')answer=state.persona==='raj'?'Raj said he stayed with Anita in Phoenix after moving to America in 1998. Finding familiar spices at a local grocery shop and making friends through the community center helped him feel at home.':'Maya said she stayed with Neha when she moved to Seattle in 2001. She brought a notebook of her mother’s recipes, and cooking together made the new place feel like home.';
else if(id==='diwali')answer=`${p().first} described Diwali as a time for everyone to come home. Preparing sweets with their mother and lighting diyas were favorite memories. Bringing people together was the part of the tradition they hoped the family would keep.`;
else if(id==='food')answer=`${p().first} remembered their mother’s dal and warm rotis as a favorite childhood meal. They learned recipes by standing beside her, and said that the time together was what made the food special.`;
else if(id==='advice')answer=`${p().first} advised listening before trying to win an argument and making time for small moments together, like a cup of tea or a walk. “It isn’t about always agreeing,” they said. “It is about remembering you are on the same team.”`;
else answer=`In “${title(s)},” ${p().first} said: “${transcript(s)}”`;
return {answer,source:id,follow:id==='love'&&!/where|location/.test(q)?'Where was the wedding?':null};}
function messageHTML(m){if(m.type==='user')return `<div class="message user">${esc(m.text)}</div>`;const s=D.stories.find(s=>s.id===m.source);return `<div class="message answer"><div class="answer-label">${I(m.missing?'info':'shield')}${m.missing?'Not in the archive yet':'From original recordings'}</div><p>${esc(m.answer)}</p>${s?`<div class="answer-source"><strong>${title(s)}</strong><p>${s.date} · Source segment ${time(s.sourceStart)}–${time(s.sourceEnd)}</p><button class="button small secondary" data-audio="${s.id}" data-segment="true">${I('play')} Hear ${p().relation} tell it</button></div>`:''}${m.missing?`<button class="text-button" style="margin-top:17px" data-queue-question="${esc(m.question)}">${I('plus')} Ask ${p().relation} next time</button>`:''}${m.follow?`<div class="suggested"><button class="suggestion" data-question="${m.follow}">Follow up: ${m.follow} ${I('arrow')}</button></div>`:''}</div>`;}
async function submitQuestion(question){if(state.busy||!question.trim())return;state.busy=true;const persona=state.persona;state.messages.push({type:'user',text:question});const node=document.querySelector('#chat-messages');node.innerHTML=state.messages.map(messageHTML).join('')+`<div class="loading"><span class="spinner"></span>Searching ${p().count} stories…</div>`;node.scrollTop=node.scrollHeight;document.querySelector('#ask-input').value='';await new Promise(r=>setTimeout(r,650));if(persona!==state.persona||state.page!=='ask'){state.busy=false;return;}state.messages.push({type:'answer',...answerFor(question)});node.innerHTML=state.messages.map(messageHTML).join('');node.scrollTop=node.scrollHeight;state.busy=false;}
function queue(){return pageTitle(`The next story starts here.`,`Questions from the family, answered one at a time in ${p().first}’s app.`,btn('Preview our app','elder','secondary','phone'))+`<div class="dashboard-columns"><section class="card"><div class="between"><h3>Questions for ${p().relation}</h3><span class="pill">${state.queues[state.persona].length} waiting</span></div><div>${state.queues[state.persona].map((q,i)=>`<div class="queue-item"><span class="queue-index">${String(i+1).padStart(2,'0')}</span><div style="flex:1"><p>${esc(q)}</p><small>${i===0?'Next question in the app':'From your family'}</small></div><button class="icon-button" data-remove-question="${i}" aria-label="Remove question ${i+1}">${I('close')}</button></div>`).join('')||'<p class="muted" style="margin:25px 0">Your queue is empty. What would you love to know?</p>'}</div><form id="queue-form" class="queue-add"><input class="input" id="queue-input" placeholder="What would you like to ask?" aria-label="New family question" maxlength="400" required><button class="button" type="submit">${I('plus')} Add question</button></form></section><aside class="card prompt-card" style="align-self:start"><span class="eyebrow">A little inspiration</span><h3>Some of the best stories begin with a small question.</h3>${['What did your childhood home smell like?','Who taught you something you still remember?','What family recipe should we learn?'].map(q=>`<button class="suggestion" data-queue-question="${esc(q)}" style="width:100%;margin-top:12px">${q} ${I('plus')}</button>`).join('')}<p class="tiny muted">One question. One answer. No pressure.</p></aside></div>`;}
function scrapbook(){return pageTitle('A life in stories.','The places, people, and moments that made them who they are.')+`<div class="scrapbook-header"><div><span class="eyebrow" style="font-size:10px">${p().name} · A living family album</span><h2>Every chapter belongs here.</h2><p>Photographs hold a moment. Stories tell you why it mattered.</p></div><img src="assets/flower.svg" alt=""></div><div class="timeline">${p().events.map(([year,name,description,image,id],i)=>`<div class="timeline-event"><span class="event-year">${year}</span><article class="card event-card" role="button" tabindex="0" data-story="${id}" aria-label="Explore ${esc(name)}"><img loading="lazy" src="assets/${image}" alt="Illustrative photograph for ${esc(name)}"><div class="event-copy"><span class="eyebrow" style="font-size:9px">Chapter ${String(i+1).padStart(2,'0')}</span><h3>${name}</h3><p>${description}</p><span class="text-button tiny">${I('play')} Explore the memory ${I('arrow')}</span></div></article></div>${i===2?`<blockquote class="quote-block">“Family traditions survive when somebody takes the time to tell the story behind them.”<small>— ${p().first} · Illustrative demo quote</small></blockquote>`:''}`).join('')}</div>`;}
function family(){return pageTitle('The people in their story.','A family tree that connects the names, faces, and memories.')+`<section class="card"><div class="between"><h3>Roots, branches, and all of us.</h3><span class="pill">3 generations</span></div><div class="tree">${[p().members.slice(0,2),p().members.slice(2,4),p().members.slice(4,6)].map(members=>`<div class="generation">${members.map(([name,role])=>`<button class="person-card" data-person="${esc(name)}">${avatar({name})}<strong>${name}</strong><p>${role}</p></button>`).join('')}</div>`).join('')}</div><div class="tree-legend"><span>${I('stories')} Select a person to explore related memories</span><span>${I('lock')} Approved family access</span></div></section><p class="tree-note">${p().first} owns their recordings. ${p().customer} helps manage this family archive with their approval.</p><div class="section-title"><h3>Sharing starts with permission.</h3><button class="text-button" data-go="privacy">Manage family access ${I('arrow')}</button></div><div class="card note-card"><div class="row">${I('shield')}<p class="muted" style="font-size:13px">Each family member’s access is approved by the storyteller. Roles and permissions are interactive demo settings.</p></div></div>`;}
const vScenario=()=>state.voiceScenario||(state.persona==='maya'?'gradual':'typical');
const vAsOf=()=>state.voiceAsOf||VOICE.END;
const vDate=(ms,year)=>new Date(ms).toLocaleDateString('en-US',Object.assign({month:'short',day:'numeric',timeZone:'UTC'},year?{year:'numeric'}:{}));
const vNum=(m,x)=>x==null?'n/a':x.toFixed(VOICE.METRICS[m].digits);
const vVal=(m,x)=>x==null?'n/a':`${vNum(m,x)} ${VOICE.METRICS[m].unit}`;
const vFlags=()=>{if(!state.consent[state.persona])return 0;const a=VOICE.analyze(vScenario());return VOICE.ORDER.filter(m=>a.metrics[m].status==='different').length;};
function vSpark(a,m){const d=a.metrics[m].daily.filter((_,i)=>i%7===0);if(d.length<2)return '';const [lo,hi]=VOICE.range(vScenario(),m),y=v=>26-((v-lo)/(hi-lo||1))*22;return `<svg class="spark" viewBox="0 0 100 30" preserveAspectRatio="none" aria-hidden="true"><polyline fill="none" stroke="${a.metrics[m].status==='different'?'#b9822f':'#6e4b9b'}" stroke-width="2" stroke-linejoin="round" points="${d.map((p,i)=>`${(i/(d.length-1))*100},${y(p.value).toFixed(1)}`).join(' ')}"/></svg>`;}
function vChart(a,mk){const M=VOICE.METRICS[mk],mm=a.metrics[mk],first=p().first,W=810,H=340,L=66,R=18,T=26,B=60,X=d=>L+(d-VOICE.START)/(VOICE.END-VOICE.START)*(W-L-R),[lo,hi]=VOICE.range(vScenario(),mk),pad=(hi-lo)*.12,ymin=lo-pad,ymax=hi+pad,Y=v=>T+(1-(v-ymin)/(ymax-ymin))*(H-T-B),step=(ymax-ymin)/4;
const ticks=[0,1,2,3,4].map(i=>ymin+i*step),months=[0,1,2,3,4,5,6,7,8].map(k=>Date.UTC(2026,k,1)).filter(d=>d>=VOICE.START);
let segs='',cur=null,prev=null;mm.daily.forEach(pt=>{const out=!!mm.spans&&mm.spans.some(sp=>pt.date>=sp[0]&&pt.date<=sp[1]);if(!cur||cur.out!==out){if(cur)segs+=`<polyline class="med${cur.out?' out':''}" points="${cur.pts.join(' ')}"/>`;cur={out,pts:prev?[prev]:[]};}const pos=`${X(pt.date).toFixed(1)},${Y(pt.value).toFixed(1)}`;cur.pts.push(pos);prev=pos;});if(cur)segs+=`<polyline class="med${cur.out?' out':''}" points="${cur.pts.join(' ')}"/>`;
const band=mm.band?`<rect class="band" x="${X(a.baselineDate)}" y="${Y(mm.band[1])}" width="${X(VOICE.END)-X(a.baselineDate)}" height="${Y(mm.band[0])-Y(mm.band[1])}" rx="4"><title>Typical range of ${esc(first)}’s 7-day median, from the first ${VOICE.BASELINE_N} recordings.</title></rect><line class="base" x1="${X(a.baselineDate)}" x2="${X(VOICE.END)}" y1="${Y(mm.baseline)}" y2="${Y(mm.baseline)}"/><text x="${X(VOICE.END)-4}" y="${Y(mm.band[1])-6}" text-anchor="end" class="bandlabel">Typical range</text><line class="basemark" x1="${X(a.baselineDate)}" x2="${X(a.baselineDate)}" y1="${T}" y2="${H-B}"/><text x="${X(a.baselineDate)+5}" y="${T+11}" class="bandlabel">Baseline set</text>`:'';
const flag=mm.status==='different'?`<line class="flag" x1="${X(mm.since)}" x2="${X(mm.since)}" y1="${T}" y2="${H-B}"/><text x="${X(mm.since)-5}" y="${H-B-8}" text-anchor="end" class="flaglabel">Outside usual range since ${vDate(mm.since)}</text>`:'';
const wait=!a.ready?`<text x="${W/2}" y="${H/2-10}" text-anchor="middle" class="waiting">Building baseline: ${a.n} of ${VOICE.BASELINE_N} recordings</text>`:'';
return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${M.label} for each recording and its 7-day median, January to September. ${mm.status==='different'?`The 7-day median has been outside ${esc(first)}’s usual range since ${vDate(mm.since)}.`:mm.status==='typical'?`The 7-day median is within ${esc(first)}’s usual range.`:'The baseline is still being built.'}"><text x="8" y="16" class="axisunit">${M.unit}</text>${ticks.map(v=>`<line class="grid-line" x1="${L}" x2="${W-R}" y1="${Y(v)}" y2="${Y(v)}"/><text x="${L-10}" y="${Y(v)+4}" text-anchor="end">${v.toFixed(M.digits)}</text>`).join('')}${band}${months.map(d=>`<text x="${X(d)}" y="${H-B+22}" text-anchor="middle">${new Date(d).toLocaleDateString('en-US',{month:'short',timeZone:'UTC'})}</text>`).join('')}${flag}${a.recs.map(r=>`<circle class="rec" data-rec="${r.id}" cx="${X(r.date).toFixed(1)}" cy="${Y(r.values[mk]).toFixed(1)}" r="3.4" tabindex="0" role="button" aria-label="Open the recording from ${vDate(r.date)}: ${vVal(mk,r.values[mk])}"><title>${vDate(r.date)} · ${vVal(mk,r.values[mk])} · open recording</title></circle>`).join('')}${segs}${wait}</svg>`;}
function voiceDyn(){const key=vScenario(),a=VOICE.analyze(key,vAsOf()),first=p().first,mk=state.voiceMetric,M=VOICE.METRICS,mm=a.metrics[mk],flagged=VOICE.ORDER.filter(m=>a.metrics[m].status==='different');
const status=!a.ready?`<span class="pill"><span class="dot"></span>Building baseline</span><h3>Getting to know ${first}’s usual.</h3><p>${a.n} of ${VOICE.BASELINE_N} recordings so far. Ranges and status appear once ${VOICE.BASELINE_N} qualifying recordings exist.</p>`:flagged.length?`<span class="pill warm"><span class="dot amber"></span>Different from usual</span><h3>Some patterns differ from usual.</h3><p>${flagged.map(m=>`${M[m].label} has been ${M[m][a.metrics[m].direction]} than ${first}’s usual range since ${vDate(a.metrics[m].since)}`).join('. ')}. A new recording in a quiet room can help confirm this.</p>`:`<span class="pill"><span class="dot"></span>Typical for ${first}</span><h3>A familiar pattern.</h3><p>All four measures are within ${first}’s usual range.</p>`;
const chip=m=>{const s=a.metrics[m].status;return s==='building'?`<span class="pill">Building baseline</span>`:s==='typical'?`<span class="pill">Typical for ${first}</span>`:`<span class="pill warm">Different from usual</span>`;};
return `<div class="voice-summary"><section class="card status-card ${flagged.length?'changed':''}">${status}</section><section class="card consent-card"><span class="eyebrow">Optional, with permission</span><h3>${first} chooses who sees this.</h3><p>Consent given by ${first} on ${p().voice.consentDate}.<br>Approved viewer: ${p().customer}.<br>Recorded about 5 to 6 times a week.</p><button class="text-button tiny" data-go="privacy" style="margin-top:13px">Manage consent ${I('arrow')}</button></section></div>
<section class="card chart-card"><div class="between"><div><h3>${M[mk].label}</h3><p class="tiny muted" style="margin-top:8px">${mm.baseline!=null?`Baseline ${vVal(mk,mm.baseline)}, the median of ${first}’s first ${VOICE.BASELINE_N} recordings.`:`Building baseline: ${a.n} of ${VOICE.BASELINE_N} recordings.`}</p></div><span class="pill blue">Demo data</span></div><div class="vtabs" role="tablist" aria-label="Measure">${VOICE.ORDER.map(m=>`<button class="vtab" role="tab" aria-selected="${m===mk}" data-vmetric="${m}">${M[m].short}</button>`).join('')}</div><div class="chart-wrap">${vChart(a,mk)}</div><div class="chart-legend"><span><span class="dot" style="background:#a881cf"></span> One recording</span><span><span class="legend-line"></span> 7-day median</span>${a.ready?'<span><span class="legend-band"></span> Typical range</span>':''}</div><p class="vfoot">n = ${a.n} recordings · same prompt type · baseline = first ${VOICE.BASELINE_N} recordings</p></section>
<div class="metric-grid">${VOICE.ORDER.map(m=>`<section class="card metric-card ${m===mk?'sel':''}" data-vmetric="${m}"><span class="eyebrow">${M[m].label}<span class="info-tip" tabindex="0" role="button" aria-label="About ${M[m].label}">${I('info')}<span class="tip" role="tooltip">${M[m].info}</span></span></span><strong>${vVal(m,a.metrics[m].current)}</strong><p>${a.metrics[m].baseline!=null?`Baseline: ${vVal(m,a.metrics[m].baseline)}`:`Baseline: ${a.n} of ${VOICE.BASELINE_N} recordings`}</p>${chip(m)}${vSpark(a,m)}</section>`).join('')}</div>`;}
function voiceBody(){const key=vScenario(),first=p().first,asOf=vAsOf();return `<div class="vtop"><div class="seg" role="radiogroup" aria-label="Demo scenario">${Object.entries(VOICE.SCENARIOS).map(([k,sc])=>`<button class="seg-btn ${k===key?'on':''}" role="radio" aria-checked="${k===key}" data-vscenario="${k}">${sc.label}</button>`).join('')}</div><div class="vasof"><label for="voice-asof">View as of <output id="voice-asof-out">${vDate(asOf,true)}</output></label><input id="voice-asof" type="range" min="${VOICE.START}" max="${VOICE.END}" step="${VOICE.DAY}" value="${asOf}"></div></div><div id="voice-dyn">${voiceDyn()}</div><p class="vsafety">${I('shield')} Describes how ${esc(first)}’s recordings compare with ${esc(first)}’s own earlier ones. Not a medical assessment.</p><div class="between voice-actions"><button class="button secondary" data-action="voice-details">${I('info')} How this works</button><button class="text-button" data-action="share-voice">${I('download')} Preview a summary for a doctor ${I('arrow')}</button></div>`;}
function refreshVoice(full){const body=document.querySelector('#voice-body');if(!body)return;if(full)body.innerHTML=voiceBody();else{const dyn=document.querySelector('#voice-dyn');if(dyn)dyn.innerHTML=voiceDyn();}const out=document.querySelector('#voice-asof-out');if(out)out.textContent=vDate(vAsOf(),true);}
function voice(){if(!state.consent[state.persona])return pageTitle('Voice patterns over time','An optional view of how recordings compare with a person’s own earlier ones.')+`<div class="card" style="padding:50px;text-align:center">${I('shield')}<h2 style="font-size:30px;margin:20px 0">${p().first}’s voice patterns are off.</h2><p class="muted" style="margin-bottom:25px">Storytelling and the archive stay available. Voice patterns need ${p().first}’s consent.</p>${btn('Review consent settings','privacy','','shield')}</div>`;return pageTitle('Voice patterns over time',`How ${p().first}’s recordings compare with ${p().first}’s own earlier ones.`)+`<div id="voice-body">${voiceBody()}</div>`;}
function privacy(){return pageTitle('Their stories remain theirs.','Manage approved family access, story visibility, and optional voice insights.')+`<div class="privacy-grid"><div class="stack"><section class="card"><div class="between"><h3>People with access</h3><span class="pill">${I('lock')} Private archive</span></div><p class="tiny muted" style="margin:14px 0">${p().first} is the recording owner. ${p().customer} manages access with their approval.</p>${p().members.map(([name,role],i)=>`<div class="access-row">${avatar({name})}<div><strong>${name}</strong><p>${role.split(' · ')[0]}</p></div>${i===0?'<span class="pill" style="margin-left:auto">Owner</span>':`<select data-permission="${esc(name)}" aria-label="Access for ${esc(name)}">${['Admin','Family member','Viewer','No access'].map(r=>`<option ${(state.permissions[state.persona][name]||(i===2?'Admin':i===4?'Viewer':'Family member'))===r?'selected':''}>${r}</option>`).join('')}</select>`}</div>`).join('')}</section><section class="card"><h3>Take your memories with you.</h3><div class="privacy-action" style="margin-top:20px">${I('download')}<div><strong>Download demo archive</strong><p>Export the sample stories, transcripts, and metadata as JSON.</p></div><button class="button small secondary" data-action="export">Export</button></div><div class="privacy-action">${I('stories')}<div><strong>Delete archive preview</strong><p>Explore the ownership flow with sample content.</p></div><button class="text-button" data-action="delete-preview" style="color:#a05e48">Preview deletion</button></div></section></div><div class="stack"><section class="card"><h3>Choose what to share.</h3><div class="toggle-row"><div><strong>Default story visibility</strong><p>Setting used for new demo stories.</p></div><select class="input" id="visibility-select" aria-label="Default story visibility" style="flex:0;min-width:150px;padding:7px">${['Family','Private','Selected people'].map(x=>`<option ${state.visibility[state.persona]===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="toggle-row"><div><strong>Voice patterns consent</strong><p>Storytelling works whether this is on or off.</p></div><label class="toggle"><input id="consent-toggle" type="checkbox" aria-label="Enable voice patterns demo consent" ${state.consent[state.persona]?'checked':''}><span></span></label></div><div class="toggle-row"><div><strong>Trusted contact</strong><p>Named in advance. Helps re-confirm consent if memory declines.</p></div><select class="input" id="trusted-select" aria-label="Trusted contact" style="flex:0;min-width:150px;padding:7px">${p().members.slice(1).map(([n])=>`<option ${n===p().customer?'selected':''}>${n}</option>`).join('')}</select></div><div class="toggle-row"><div><strong>Re-confirm consent</strong><p>A gentle reminder from the app.</p></div><select class="input" aria-label="Consent reminder" style="flex:0;min-width:150px;padding:7px">${['Every 6 months','Every 3 months','Every year'].map(x=>`<option>${x}</option>`).join('')}</select></div><p class="tiny muted" style="margin-top:17px">Prototype controls only. Access is simulated locally; do not enter private information in this demo.</p></section><section class="card note-card"><span class="eyebrow" style="font-size:9px">Our promise</span><h3>Real words. Real memories.</h3><p style="margin-top:15px">${I('check')} No voice cloning or impersonation.</p><p>${I('check')} Answers always link to their source.</p><p>${I('check')} Missing memories are never invented.</p><p>${I('check')} Voice patterns require consent.</p><p>${I('check')} The storyteller remains in control.</p></section></div></div>`;}
function elder(){const question=state.queues[state.persona][0]||D.initialQueue[0];return `<div class="our-app ${state.largeText?'large':''}" id="our-app"><a class="skip-link" href="#phone-content">Skip to question</a><header class="oa-bar">${brand()}<div class="oa-tools"><button class="oa-toggle" data-action="toggle-text" aria-pressed="${state.largeText?'true':'false'}">${I('plus')} Larger text</button><button class="text-button" data-go="home">Family view</button></div></header><main class="oa-main"><section class="oa-card" id="phone-content" aria-live="polite">${elderContent(question)}</section><p class="oa-safe">${I('lock')} Only the family you approve can hear your stories.</p><ol class="oa-steps" aria-label="How it works"><li><strong>A question arrives.</strong> Someone who loves you asked it.</li><li><strong>You tell the story.</strong> Press the big button and talk.</li><li><strong>Your family keeps it.</strong> In your own voice, always.</li></ol><p class="oa-demo">Demo: the recorder is simulated and nothing is saved or sent.</p></main></div>`;}
function elderContent(question){const person=p();if(state.recordStage==='recording')return `<h1 class="oa-title">We’re listening, ${person.first}.</h1><p class="oa-sub">Take your time. Tell it the way you remember it.</p><div class="oa-timer" id="record-timer" role="timer">${time(state.recordSeconds)}</div>${wave(40)}<button class="oa-big stop" data-action="stop-recording">${I('check')} I’m finished</button><button class="oa-link" data-action="cancel-recording">Start over</button>`;
if(state.recordStage==='saved')return `<div class="check-circle oa-check">${I('check')}</div><h1 class="oa-title">Thank you, ${person.first}.</h1><p class="oa-sub">Your story is saved. ${esc(person.customer.split(' ')[0])} and the family will be able to hear it.</p><div class="transcript oa-transcript">“${D.recordingTranscript.slice(0,180)}…”</div><p class="oa-note">Sample transcript</p><button class="oa-big" data-action="next-recording">${I('heart')} Done</button>`;
return `<div class="oa-hello">${avatar(person,true)}<p>Hello, ${person.first}.</p></div><p class="oa-label">${esc(person.customer.split(' ')[0])} would like to know:</p><h1 class="oa-question">${esc(question)}</h1><button class="oa-big record" data-action="start-recording"><span class="oa-ring">${I('mic')}</span>Tell my story</button><p class="oa-sub">Press the button and start talking.</p><button class="oa-link" data-action="skip-question">Ask me something else</button>`;}
function time(n){return `${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`;}
function render(){stopPlayback();clearInterval(recordTimer);if(state.recordStage==='recording')state.recordStage='ready';document.title=`${D.brand} — ${state.page==='landing'?'A better way to remember them.':nav.find(n=>n[0]===state.page)?.[1]||'Our app'}`;const pages={home,stories,ask,queue,scrapbook,family,voice,privacy,elder};document.querySelector('#app').innerHTML=state.page==='landing'?landing():state.page==='elder'?elder():shell((pages[state.page]||home)());if(state.page==='stories')updateStoryResults();}
function go(page){closeModal();state.page=page;location.hash=page;render();window.scrollTo(0,0);}
function toast(message){clearTimeout(toastTimer);const node=document.querySelector('#toast');node.textContent=message;node.classList.add('show');toastTimer=setTimeout(()=>node.classList.remove('show'),3500);}
function modal(titleText,body,sub=''){previousFocus=document.activeElement;document.querySelector('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(titleText)}"><header class="modal-head"><div><h2>${titleText}</h2>${sub?`<p class="tiny muted">${sub}</p>`:''}</div><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${I('close')}</button></header><div class="modal-body">${body}</div></section></div>`;document.body.style.overflow='hidden';document.querySelector('.modal [data-action="close-modal"]').focus();}
function closeModal(){stopPlayback();document.querySelector('#overlay').innerHTML='';document.body.style.overflow='';if(previousFocus?.isConnected)previousFocus.focus();}
function audioPlayer(s,segment=false){return `<div class="audio-player"><div class="row"><button class="circle-play" data-play="${s.id}" data-segment="${segment}" aria-label="${s.audio?'Play original recording':'Start simulated playback'}">${I('play')}</button>${wave(52)}</div><div class="audio-info"><span id="playback-time">${segment?time(s.sourceStart):'0:00'}</span><span>${s.audio?'Original audio':'Simulated playback · add your original clip'}</span><span>${segment?time(s.sourceEnd):s.length}</span></div></div>`;}
function storyModal(id,segment=false){const s=D.stories.find(s=>s.id===id);if(!s)return;modal(title(s),`<img class="modal-photo" src="assets/${s.image}" alt="Illustrative memory photograph"><div class="between"><span class="pill">${s.category}</span><span class="tiny muted">${s.date} · ${s.length}</span></div>${audioPlayer(s,segment)}<h3 style="font-size:24px">The story, in ${p().first}’s words</h3><div class="transcript">${transcript(s)}</div><div class="tags">${s.tags.map(t=>`<span class="pill">${t}</span>`).join('')}</div><p class="tiny muted">Fictional sample transcript and illustrative photography. Your team’s recorded audio can replace the playback placeholder.</p><div class="modal-actions">${btn('Ask about this memory','ask','small','ask')}<button class="button small secondary" data-action="close-modal">Back to the archive</button></div>`,`${p().name}’s family archive`);}
function stopPlayback(){clearInterval(audioTimer);if(activeAudio){activeAudio.pause();activeAudio=null;}document.querySelectorAll('.waveform.playing').forEach(x=>x.classList.remove('playing'));document.querySelectorAll('[data-play]').forEach(x=>{x.innerHTML=I('play');x.setAttribute('aria-label','Start playback');});}
function play(button,id,segment){const s=D.stories.find(s=>s.id===id);if(button.classList.contains('playing-button')){button.classList.remove('playing-button');stopPlayback();return;}stopPlayback();document.querySelectorAll('.playing-button').forEach(x=>x.classList.remove('playing-button'));button.classList.add('playing-button');button.innerHTML=I('pause');button.setAttribute('aria-label','Pause playback');const player=button.closest('.audio-player'),waveNode=player.querySelector('.waveform');waveNode.classList.add('playing');let position=segment?s.sourceStart:0;const end=segment?s.sourceEnd:Number(s.length.split(':')[0])*60+Number(s.length.split(':')[1]);if(s.audio){activeAudio=new Audio(s.audio);activeAudio.addEventListener('loadedmetadata',()=>{activeAudio.currentTime=position;});activeAudio.addEventListener('error',()=>{stopPlayback();toast('This clip could not be played. Check its file path.');});activeAudio.play().catch(()=>{stopPlayback();toast('Audio unavailable. Add your original recording to the demo.');});}else toast('Simulated playback — no voice recording has been added yet.');audioTimer=setInterval(()=>{position=activeAudio?Math.floor(activeAudio.currentTime):position+1;const t=player.querySelector('#playback-time');if(t)t.textContent=time(position);if(position>=end){button.classList.remove('playing-button');stopPlayback();}},1000);}
function addQueue(question){const list=state.queues[state.persona];if(list.includes(question)){toast('That question is already waiting.');return;}list.push(question);toast(`Added to ${p().first}’s question queue.`);if(state.page==='queue')render();else{const badge=document.querySelector('.nav-count');if(badge)badge.textContent=list.length;}}
function exportArchive(){const blob=new Blob([JSON.stringify({brand:D.brand,demo:true,persona:p(),stories:D.stories.map(s=>({...s,title:title(s),transcript:transcript(s)})),questions:state.queues[state.persona]},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`${p().family.toLowerCase()}-demo-archive.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),500);toast('Sample archive exported.');}
document.addEventListener('click',e=>{const vsc=e.target.closest('[data-vscenario]');if(vsc){state.voiceScenario=vsc.dataset.vscenario;refreshVoice(true);document.querySelector(`[data-vscenario="${state.voiceScenario}"]`)?.focus();return;}const vrec=e.target.closest('[data-rec]');if(vrec){storyModal(D.stories[(+vrec.dataset.rec)%D.stories.length].id);return;}const vtab=e.target.closest('[data-vmetric]');if(vtab&&!e.target.closest('.info-tip')){state.voiceMetric=vtab.dataset.vmetric;refreshVoice();document.querySelector(`.vtab[data-vmetric="${state.voiceMetric}"]`)?.focus();return;}const goButton=e.target.closest('[data-go]');if(goButton){go(goButton.dataset.go);return;}const story=e.target.closest('[data-story]');if(story){storyModal(story.dataset.story);return;}const audio=e.target.closest('[data-audio]');if(audio){storyModal(audio.dataset.audio,true);return;}const question=e.target.closest('[data-question]');if(question){submitQuestion(question.dataset.question);return;}const add=e.target.closest('[data-queue-question]');if(add){addQueue(add.dataset.queueQuestion);return;}const filter=e.target.closest('[data-filter]');if(filter){state.filter=filter.dataset.filter;document.querySelectorAll('.filter-chip').forEach(x=>x.classList.toggle('active',x===filter));updateStoryResults();return;}const remove=e.target.closest('[data-remove-question]');if(remove){state.queues[state.persona].splice(Number(remove.dataset.removeQuestion),1);render();toast('Question removed.');return;}const playButton=e.target.closest('[data-play]');if(playButton){play(playButton,playButton.dataset.play,playButton.dataset.segment==='true');return;}const person=e.target.closest('[data-person]');if(person){const name=person.dataset.person,first=name.split(' ')[0];const related=D.stories.filter(s=>s.people.includes(first)||transcript(s).includes(first));modal(`${name}’s story connections`,related.length?`<p>Memories that mention ${first} in the sample archive.</p><div class="story-grid two" style="margin-top:20px">${related.map(storyCard).join('')}</div>`:`<p>No sample stories mention ${first} yet. Invite a new memory with a question.</p><button class="button" data-queue-question="What is your favorite memory of ${esc(first)}?" style="margin-top:22px">${I('plus')} Add a family question</button>`);return;}if(e.target.classList.contains('modal-backdrop')){closeModal();return;}const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;
if(action==='close-modal')closeModal();
if(action==='notifications')modal('A little family update',`<div class="stack"><div class="card"><span class="eyebrow" style="font-size:10px">A memory added</span><h3>${p().first} shared a new story.</h3><p class="muted" style="margin-top:13px">“How I Met Your ${state.persona==='raj'?'Grandmother':'Grandfather'}” is ready to explore.</p><button class="text-button" data-story="love">Explore the memory ${I('arrow')}</button></div>${state.persona==='maya'&&state.consent.maya?'<div class="notice">Voice patterns update: Maya’s recent recordings differ from her usual range. This is not a medical assessment.</div>':''}</div>`,'Family updates');
if(action==='start-recording'){state.recordStage='recording';state.recordSeconds=0;document.querySelector('#phone-content').innerHTML=elderContent();recordTimer=setInterval(()=>{state.recordSeconds++;const t=document.querySelector('#record-timer');if(t)t.textContent=time(state.recordSeconds);},1000);}
if(action==='stop-recording'){clearInterval(recordTimer);state.recordStage='saved';state.saved[state.persona]++;if(state.queues[state.persona].length)state.queues[state.persona].shift();document.querySelector('#phone-content').innerHTML=elderContent();toast('Demo story saved to this family’s session.');}
if(action==='cancel-recording'||action==='next-recording'){clearInterval(recordTimer);state.recordStage='ready';document.querySelector('#phone-content').innerHTML=elderContent(state.queues[state.persona][0]||D.initialQueue[0]);}
if(action==='skip-question'){const list=state.queues[state.persona];if(list.length>1)list.push(list.shift());else if(!list.length)list.push(D.initialQueue[1]);else list.push(D.initialQueue.find(q=>q!==list[0]));render();}
if(action==='toggle-text'){state.largeText=!state.largeText;document.querySelector('#our-app').classList.toggle('large',state.largeText);e.target.closest('[data-action]').setAttribute('aria-pressed',String(state.largeText));}
if(action==='export')exportArchive();
if(action==='voice-details')modal('How voice patterns work',`<p>Each measure is compared only with the same person’s own earlier recordings. Nothing is compared with other people, so accents, languages and naturally slow or fast speakers are treated fairly.</p><div class="stack" style="margin-top:22px">${[['Baseline',`The median of the first ${VOICE.BASELINE_N} qualifying recordings. Until then, no range or status is shown.`],['Typical range','The baseline plus or minus two standard errors of a 7-day median, using the spread of the baseline recordings. It shows how much a week’s median normally moves.'],['Status','“Typical” means the 7-day median is inside the range. “Different from usual” means it has been outside the range for 7 days in a row. A single odd day never changes the status.'],['Which recordings count','Only the same prompt type and device class, and never recordings flagged for low audio quality.'],['Measures',VOICE.ORDER.map(m=>`${VOICE.METRICS[m].label}: ${VOICE.METRICS[m].info}`).join(' ')]].map(([a,b])=>`<div><strong>${a}</strong><p class="muted" style="font-size:14px;margin-top:6px">${b}</p></div>`).join('')}</div><div class="notice" style="margin-top:25px">Speech varies with mood, tiredness, topic and the room. This is not a medical assessment. If you have a health concern, talk to a qualified healthcare professional.</div>`);
if(action==='share-voice'){const a=VOICE.analyze(vScenario(),vAsOf()),M=VOICE.METRICS,first=p().first;modal('Summary for a doctor',`<span class="pill blue">Preview · Nothing is sent</span><h3 style="margin:23px 0 15px">${p().name} · Voice patterns</h3>${a.ready?`<p>${a.n} qualifying recordings through ${vDate(a.asOf,true)}, compared with ${first}’s own baseline (first ${VOICE.BASELINE_N} recordings).</p><div class="stack" style="margin-top:16px">${VOICE.ORDER.map(m=>{const x=a.metrics[m];return `<div><strong>${M[m].label}</strong><p class="muted" style="font-size:14px;margin-top:4px">${vVal(m,x.current)} now, baseline ${vVal(m,x.baseline)}, typical range ${vNum(m,x.band[0])} to ${vNum(m,x.band[1])}. ${x.status==='different'?`${M[m][x.direction][0].toUpperCase()+M[m][x.direction].slice(1)} than usual since ${vDate(x.since)}.`:'Within the usual range.'}</p></div>`;}).join('')}</div>`:`<p>${a.n} of ${VOICE.BASELINE_N} recordings so far. A summary is available once the baseline is built.</p>`}<p style="margin-top:18px" class="muted">This describes how recordings compare with ${first}’s own earlier ones. It is not a medical assessment. Shared by ${first} with ${p().customer}; consent can be withdrawn in Privacy & access.</p><div class="modal-actions"><button class="button secondary" data-action="close-modal">Done</button></div>`);}
if(action==='delete-preview')modal('Archive deletion preview',`<p>The storyteller can choose to remove their recordings. This prototype contains fictional demo content, so this preview only explains the flow.</p><div class="notice" style="margin-top:22px">In a real archive, deletion would require the storyteller’s approval and clear information about recovery and backups.</div><div class="modal-actions"><button class="button secondary" data-action="close-modal">Keep the demo archive</button><button class="button danger" data-action="reset-demo">Reset local demo settings</button></div>`);
if(action==='reset-demo'){state.permissions[state.persona]={};state.visibility[state.persona]='Family';state.saved[state.persona]=0;state.consent[state.persona]=true;state.messages=[];state.queues[state.persona]=state.persona==='raj'?[...D.initialQueue]:['What was your first job, and what did it teach you?','What was Mom like as a child?','What tradition do you hope we keep?'];closeModal();render();toast('Local demo settings reset.');}
});
document.addEventListener('submit',e=>{if(e.target.id==='ask-form'){e.preventDefault();submitQuestion(document.querySelector('#ask-input').value.trim());}if(e.target.id==='queue-form'){e.preventDefault();const field=document.querySelector('#queue-input');if(field.value.trim())addQueue(field.value.trim());}});
document.addEventListener('input',e=>{if(e.target.id==='voice-asof'){state.voiceAsOf=+e.target.value;refreshVoice();return;}if(e.target.id==='story-search'){state.search=e.target.value;updateStoryResults();}});
document.addEventListener('change',e=>{if(e.target.id==='family-select'){state.persona=e.target.value;state.voiceScenario=null;state.voiceAsOf=null;state.messages=[];state.search='';state.filter='All';state.recordStage='ready';state.busy=false;closeModal();render();toast(`Now viewing ${p().family} family · ${p().customer}.`);}if(e.target.dataset.permission){state.permissions[state.persona][e.target.dataset.permission]=e.target.value;toast('Demo permission updated.');}if(e.target.id==='consent-toggle'){state.consent[state.persona]=e.target.checked;toast(`Voice patterns ${e.target.checked?'enabled':'disabled'} in the demo.`);}if(e.target.id==='visibility-select'){state.visibility[state.persona]=e.target.value;toast('Default demo visibility updated.');}});
document.addEventListener('keydown',e=>{const backdrop=document.querySelector('.modal-backdrop');if(e.key==='Escape')closeModal();if(backdrop&&e.key==='Tab'){const focusable=[...backdrop.querySelectorAll('button,[href],input,select,[tabindex="0"]')].filter(x=>!x.disabled);const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role="button"][data-story]')){e.preventDefault();storyModal(e.target.dataset.story);}});
window.addEventListener('hashchange',()=>{const page=location.hash.slice(1);if(['landing',...nav.map(n=>n[0]),'elder'].includes(page)&&state.page!==page){state.page=page;closeModal();render();window.scrollTo(0,0);}});
render();

document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches&&e.target.matches('[data-rec]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
